// Parse the file content into JSON
const fileData = $input.first().json.data;
const statusData = JSON.parse(fileData);

// Route through status-router code node logic
const rawStatus = statusData.overall_status;
const status = (typeof rawStatus === 'string' && rawStatus.trim().length > 0)
  ? String(rawStatus).trim().toUpperCase()
  : 'UNKNOWN';

let route = 'UNKNOWN';
let severity = 'review';
let canNotify = false;
let canStartNextRun = false;
let requiredHumanReview = true;

if (status === 'RED_BLOCK') {
  route = 'BLOCK'; severity = 'critical'; canNotify = true;
  canStartNextRun = false; requiredHumanReview = true;
} else if (status === 'YELLOW_REVIEW' || status === 'NEEDS_VALIDATION') {
  route = 'REVIEW'; severity = 'warning'; canNotify = true;
  canStartNextRun = false; requiredHumanReview = true;
} else if (status === 'GREEN_SAFE') {
  route = 'GREEN'; severity = 'info'; canNotify = false;
  canStartNextRun = true; requiredHumanReview = false;
} else if (status === 'TOOL_GAP') {
  route = 'TOOL_GAP'; severity = 'warning'; canNotify = true;
  canStartNextRun = false; requiredHumanReview = true;
} else if (status === 'STALE') {
  route = 'STALE'; severity = 'info'; canNotify = true;
  canStartNextRun = false; requiredHumanReview = true;
} else {
  route = 'UNKNOWN'; severity = 'review'; canNotify = true;
  canStartNextRun = false; requiredHumanReview = true;
}

return [{ json: { ...statusData, route, severity, canNotify, canStartNextRun, requiredHumanReview } }];

// Redaction: strip run_path, summarize artifacts
function redactRun(run) {
  if (!run || typeof run !== 'object') return null;
  return {
    run_id: String(run.run_id || 'UNKNOWN'),
    per_run_status: String(run.per_run_status || 'UNKNOWN'),
    classification: String(run.classification || 'UNKNOWN'),
    is_stale: Boolean(run.is_stale),
    agent_was_launched: Boolean(run.agent_was_launched),
    decision: run.decision || null,
    can_start_next_run: run.can_start_next_run === true,
    required_human_review: run.required_human_review === true,
    mission_title: String(run.mission_title || 'Unknown Mission'),
    agent_status: run.agent_status || 'UNKNOWN',
    agent_exit_code: run.agent_exit_code != null ? Number(run.agent_exit_code) : null,
    runner_exit_code: run.runner_exit_code != null ? Number(run.runner_exit_code) : null,
    agent_self_assessment: String(run.agent_self_assessment || 'UNKNOWN'),
    controller_reason: String(run.controller_reason || ''),
    artifacts_summary: {
      present_count: Array.isArray(run.artifacts_present) ? run.artifacts_present.length : 0,
      missing_count: Array.isArray(run.artifacts_missing) ? run.artifacts_missing.length : 0,
      invalid_count: Array.isArray(run.artifacts_invalid) ? run.artifacts_invalid.length : 0
    },
    warnings_count: Array.isArray(run.warnings) ? run.warnings.length : 0
  };
}

const data = $input.first().json;
const runs = Array.isArray(data.runs) ? data.runs.map(redactRun).filter(Boolean) : [];

return [{
  json: {
    project: String(data.project || 'unknown'),
    generated_at: data.generated_at || new Date().toISOString(),
    overall_status: String(data.overall_status || 'UNKNOWN'),
    runs_found: Number(data.runs_found) || runs.length,
    runs_with_controller_decision: Number(data.runs_with_controller_decision) || 0,
    runs_with_agent_launched: Number(data.runs_with_agent_launched) || 0,
    stale_runs: Number(data.stale_runs) || 0,
    global_warnings_count: Array.isArray(data.global_warnings) ? data.global_warnings.length : 0,
    latest_run_id: String(data.latest_run_id || 'UNKNOWN'),
    can_start_next_run: data.canStartNextRun === true,
    required_human_review: data.requiredHumanReview !== false,
    runs: runs,
    redacted: true,
    redacted_at: new Date().toISOString(),
    redaction_note: 'run_path removed, artifacts summarized as counts. See dashboard/output/status.json for full details.'
  }
}];
